    ph_in: { emoji: '📥', label: 'in / into — усередину', parent: 'phrasal' },
    ph_back: { emoji: '🔙', label: 'back / away — назад, геть', parent: 'phrasal' },
    ph_over: { emoji: '🔄', label: 'over, through, around — через, навколо', parent: 'phrasal' },
